import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SurfLog.html","title":"SurfLog","lang":"en-US","frontmatter":{},"git":{"createdTime":1744200337000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":62}]},"readingTime":{"minutes":6.61,"words":1984},"filePathRelative":"SurfLog.md"}`),a={name:`SurfLog.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="surflog" tabindex="-1"><a class="header-anchor" href="#surflog"><span>SurfLog</span></a></h1><ul><li><a href="./サーフィン.html">サーフィン</a><ul><li><a href="./サーフボード.html">サーフボード</a></li><li><a href="./SurfLogの過去ログ.html">SurfLogの過去ログ</a><ul><li><a href="./SurfLog_202512から202603まで.html">SurfLog_202512から202603まで</a> 2025〜2026の冬の奄美</li><li><a href="./SurfLog_202604から202608まで.html">SurfLog_202604から202608まで</a> 2026年の春〜夏</li></ul></li></ul></li></ul><p>サーフィン関連の日々の雑記などのブログ的な内容をここに置く。</p><h2 id="このページの主旨" tabindex="-1"><a class="header-anchor" href="#このページの主旨"><span>このページの主旨</span></a></h2><p>サーフィン関連の成長などを見たいと思った時に、雑記の中に埋もれているのはいまいちだよなぁ、という事でここに独立させてみる。 本当はブログの方にしたい気もするが、まぁいいだろう。</p><p>単に思った事などを書いたり課題とか考えてる事を書いたりしてみる。</p><h2 id="_2026-09-02-水" tabindex="-1"><a class="header-anchor" href="#_2026-09-02-水"><span>2026-09-02 (水)</span></a></h2><p>立つだけって感じだったがしばらく海入れてないので入っておく。サイズはコシくらいあるんだが、なんか上しか割れないでいまいち。 最干に入ったがあんまり浅くなくて深すぎる感じだった。</p><p>なんか今日はパドルが調子良くて、手を入れた所からずっと水をつかめている感じがあった。なんでだろう？水泳でもたまにこういう事あったのだがいまいち理由は良く分かってないんだよなぁ。</p><h2 id="_2026-09-03-木" tabindex="-1"><a class="header-anchor" href="#_2026-09-03-木"><span>2026-09-03 (木)</span></a></h2><p>昨日よりワンサイズ上がってハラくらいのセットもあったが、昨日よりもまとまりが無くていまいち。まぁ立てる波の本数は多いので多少はマシか。 たまのセットはそれなりのサイズがあり、その中のたまにまとまりのあるのもあるが、かなり本数は少ない。</p><p>今日はパドルとドルフィンを意識してやっていた。ドルフィンは結構深く潜れている気がする。</p><p>ライディングはまぁ見る所無し。テイクオフもまぁいまいちだが、一応前に重心を残す立ち方を練習はしている。</p><h2 id="_2026-09-04-金" tabindex="-1"><a class="header-anchor" href="#_2026-09-04-金"><span>2026-09-04 (金)</span></a></h2><p>なかなか割れないので駄目元で入ったら意外と割れるようになった。ただタルめで乗ってもいまいちではあったが。 こういう日は単にパドル全力でひっかけるだけでテクニック的な部分があまり鍛えられないのでテイクオフの練習としては微妙だが、 たくさんパドルしたのとまぁ乗れはしたのでそれなりには遊べた。 もうちょいひいてればいい波なんだけどな〜。</p><h2 id="_2026-09-07-月" tabindex="-1"><a class="header-anchor" href="#_2026-09-07-月"><span>2026-09-07 (月)</span></a></h2><p>今朝は台風の大雨の予報だったが意外と雨も弱く、風も強い予報だったがあまり吹いて無くて普通に出来た。 ボードは久しぶりに<a href="./HT2.html">HT2</a>。</p><p>ただ干潮のあたりだったので結構浅く、コケて岩に叩きつけられてウニが刺さったりする事もあった。 かなり掘れ上がる波で二つになってしまったりといいのが少ないが、たまにあるいいのをつかめれば良い波、という感じ。</p><p>風が冷たかったので今日はタッパーで入る。ちょうどいいくらいだな。ラッシュガードはもう寒い感じだ。</p><p>ライディングは可も無く不可も無し、という程度。HT2に慣れるのに時間を使った感じでもある。 波の乗る場所が良くないのが多かったが、掘れる難しい波なので実力って感じだなぁ。</p><h2 id="_2026-09-08-火" tabindex="-1"><a class="header-anchor" href="#_2026-09-08-火"><span>2026-09-08 (火)</span></a></h2><p>少しサイズは下がったがまだまだ乗れる感じ。 時間帯によっていまいちだったり良くなったりという感じだが、総じて、まぁまぁ良かったと思う。</p><p>今日はいい波用の練習を考えよう、という事で、カービングでも練習するか、と思う。</p><p>以下の動画を参考に、後ろに倒れる感じの下に落とすカービングを目指す。</p><p><a href="https://www.youtube.com/watch?v=oBGvInMBrsg&amp;sttick=0" target="_blank" rel="noopener noreferrer">【カービング】和光大プロのコーチング〜サーフィンが上手くなりたい全ての人へ〜 - YouTube</a></p><p>何本かいい感じのが出来た。ただセクション次第では全然上手く行かない。 これが出来るのは波によるんだな、という当たり前の事を学ぶ。 あとボトムが思ったより無い時などにもうまく対応出来ない。本当はボトムの状態に合わせていろいろ変えられるといいんだろうが。 ただ後ろにそらす事で左側のレールを入れる、というのはかなり良さそう。これを練習していきたい。</p><p>昼頃になって人が増えてきたので譲って上げるか、と上がる事に。結構いい波乗れた。</p><p>あとコシサイズのようにテイクオフしよう運動は、ムネカタくらいなら割と出来るようになってきている気もする。波によるが。 乗る前に少し波側に意識を留めるのが結構効いている気がする。</p><p>なお、昨日は結構寒かったが今日は暑かった。タッパーで入ったがラッシュガードの方が良かったなぁ。</p><h2 id="_2026-09-09-水" tabindex="-1"><a class="header-anchor" href="#_2026-09-09-水"><span>2026-09-09 (水)</span></a></h2><p>今日はオンショアビュービューで夕方落ちるという予報にかけて行ったら波がサイズダウンしたのと満ちて割れにくくなったのと思ったより波がまとまるのが遅くいまいち。 まぁたまに乗れるのも来ていたが、ライディングは見るべきものは無し。まぁこういう日もある。</p><h2 id="_2026-09-14-月" tabindex="-1"><a class="header-anchor" href="#_2026-09-14-月"><span>2026-09-14 (月)</span></a></h2><p>オンショアで鵠沼のライブカメラが空いてたしちょっと乗れそうだったので鵠沼に行ってくる。 ジャンクなのでちょっと走る程度という感じではあったが、本数は多いのでテイクオフの練習にはなった。 特に上達という感じでは無いが、時間があくと波を直前まで見るのができなくなる事がちょくちょくあるので、 ちゃんと直前まで見ながらいい所で立つ、という感じになるように練習して、後半は割と出来た気はする。</p><p>今日みたいなぐちゃぐちゃ系の波では直前まで見るのは結構大切だよなぁ。</p><h2 id="_2026-09-15-火" tabindex="-1"><a class="header-anchor" href="#_2026-09-15-火"><span>2026-09-15 (火)</span></a></h2><p>夕方に材木座見たらちょっと乗れそうだったので入ってみる。入ってみるとサイズはたまにコシくらいのも来るのだがパワーが全然無くて全く走れず立つだけ。 まぁテイクオフの練習にはそれなりになった。</p><h2 id="_2026-09-22-火" tabindex="-1"><a class="header-anchor" href="#_2026-09-22-火"><span>2026-09-22 (火)</span></a></h2><p>ここ4日はずっとサーフィンだったがハズレも多い。</p><p><strong>2026-09-19 土</strong></p><p>サイズはそんなでも無いが、ちょっと乗れるくらい。 入った時はちょっと乗れたが、オフショアがどんどん強くなっていまいちに。 たまにインサイドまでつながる奴はオフショアなりにライディングも出来た。</p><p><strong>2026-09-20 日</strong></p><p>サイズはあがってきたがオフショアがかなり強くて微妙。サイズもそこまででも無し。 アウトまで行ったが間隔長すぎて戻ってくる。 全体的に不発。</p><p>夕方風が落ちたので1時間くらい入る。そんなに大きくは無かったが、グーフィーはそれなりのも乗れた。 午前よりは良かったが台風としては微妙。</p><p><strong>2026-09-21</strong></p><p>暴風雨で大荒れではあるが、たまに雨やんだりたまに風やんだりもしていて、サイズはめちゃ上がった。ダブルオーバーで形は結構良さそうだがオフが強くて一本も乗れず。 ただでかいサイズになれるべく何本か突っ込んでパーリングする。少し慣れてきたのでいけるか？という感じになってきたら風がさらに強くなってしまったのもあり、心が折れて帰る。 大雨。</p><p><strong>2026-09-22 (火)</strong></p><p>一気にサイズダウンでハラムネくらいになってしまった。 そんなにショルダーが続く感じでも無いが少しは乗れるし形も綺麗なので、台風と思わなければ遊べる日ではあった。</p><p>今日はパドルがだいぶ進むようになったが、やっぱりここ数日全然進まなかったのはオフショアのせいか。</p><p>全体的に今回の台風は不発だったが、まぁ波があっただけ良しという感じもする。</p><h2 id="_2026-09-28-月" tabindex="-1"><a class="header-anchor" href="#_2026-09-28-月"><span>2026-09-28 (月)</span></a></h2><p>オンショアの風波だが少し乗れそうなくらいはあったので入ってみた。 一瞬乗れたがすぐに満ちてきて本数が減った上にゴミが多すぎてうんざりしてすぐにあがってしまう。</p><p>湾内で少し立つだけのを何本か乗ったが、こちらもそのうち無くなってしまい上がる。</p><p>湾内では少しテイクオフの練習にはなった。</p><h2 id="_2026-09-30-水" tabindex="-1"><a class="header-anchor" href="#_2026-09-30-水"><span>2026-09-30 (水)</span></a></h2><p>昨日は入った時はムネカタくらいのサイズがあって結構良かったが数本乗ったら来なくなってしまった。 そのあとはコシハラくらいのたるめの波が来ていたのでインサイドで遊んでる分にはそれなりに遊べた。</p><p>今日はハラムネくらいの波がずっと来続けて、クリーンですこしのりしろもある感じで悪くはなかった。 レギュラーはいい奴はいいカーブが一発入り、それ以外のもカットバックくらいしか出来ないがちゃんと戻れる程度にはフェースがある感じで、 カットバックの良い練習にはなった。</p><p>グーフィーは最初にいいセクションがあるので一発リップの練習が出来る感じだった。 バックサイド、ちょうど以下の動画を昨日見ていたので、</p><p><a href="https://www.youtube.com/watch?v=Rg6ty06eGcI" target="_blank" rel="noopener noreferrer">かっこ悪いサーフィンスタイルを今すぐ卒業！めちゃくちゃイメージしやすいライディングトレーニング方法とは？ - YouTube</a></p><p>これをイメージした所、バックサイドのボトムターンが凄く良くなった。腰を前に向けるというのがやりやすくて、いいリップが出来た。 ハラくらいの波のバックサイドのボトムターンは凄く良くなったと思う。 今日はバックサイドが成長したので気分が良い。</p><p>今日は本数が多かった割に人が少なかったのでたくさん乗れて、結構良かった。 雨降ってて寒いおかげだね。</p><h2 id="_2026-10-01-木" tabindex="-1"><a class="header-anchor" href="#_2026-10-01-木"><span>2026-10-01 (木)</span></a></h2><p>波が思ったより無くなってしまったので遊びでロングボードで入ってみた。 最初は全然乗れなかったが、最後の方は横に走れるくらいにはなった。でもボトムターンとかは全然出来ない。</p><p>もう少し乗ってみてもいいかもしれん。</p><h2 id="_2026-10-05-月" tabindex="-1"><a class="header-anchor" href="#_2026-10-05-月"><span>2026-10-05 (月)</span></a></h2><p>一応台風という事だがそこまででかくもならず。 ただ入ったタイミングは割と良くて、うねりのサイズは頭以上で結構大きかった。下の方がなだらかなので実質ムネカタくらいだが、 ムネカタの波はまぁそれなりの大きさだよな。 オフショアがまぁまぁ吹いてて、ウォールが長い状態でしばらくもつ感じで、 どこで何やるのかは結構悩む波だった。 ただカットバックやカーブをやるには十分なくらい張ってるので、かなり遊べる方の波ではあった。 もうちょっと浅ければもっといい波だったんだろうけれど、満ちている割には遊べた。</p><p>今日はオフショアのせいでテイクオフの所が簡単な感じになってしまって、しかもオフショアでまぁまぁガタついているのでテイクオフの練習としては微妙だった。 ボトムがならだかになってしまっているのでボトムターンも微妙で、 最近課題にしている事はあまり練習出来ない波だった。</p><p>途中満潮になってちょっとサイズ落ちてからは人も増えてしまっていまいちになったのでちょっと早めにあがってきたが、 全体としては結構遊べる方だったかな。いいタイミングで入れた。</p><p>今日はカットバックを結構練習した。戻りすぎると失速してしまって前に戻れない事もあったが、 まぁまぁ出来ているような気もする。 カットバックはプロの動画とか見ていても上手い下手が結構あるよな。カットバック上手いのはかっこいいので上手くなりたい。</p><p>うちのホームポイントはあんまりカットバック向きの波では無い事が多いので、たまにしか練習出来ないんだよなぁ。</p><h2 id="_2026-10-06-火" tabindex="-1"><a class="header-anchor" href="#_2026-10-06-火"><span>2026-10-06 (火)</span></a></h2><p>今日は割と台風っぽい波で、アウトで乗れた。サイズは頭オーバーくらいで、それなりにフェースもある。 オフショアはそれなりに吹いているがまぁ乗れた。</p><p>ただだんだん潮が満ちてきて割れづらくなったりワイドになってきたりして、最後はあまり乗れなかった。 しかもインサイドは大混雑。すぐ上がれば良かったなぁ。</p><p>今日はカットバックを練習しようと意気込んで行ったが、あまり出来なかった。いいカーブが入る感じだったのでカーブは結構出来たが、テーマを持って練習は出来ず、 単に乗っただけという感じではある。 ただまぁまぁ大きい波だったのでカーブが入ると気分はいいね。</p><h2 id="_2026-10-07-水" tabindex="-1"><a class="header-anchor" href="#_2026-10-07-水"><span>2026-10-07 (水)</span></a></h2><p>今日はいい波と聞いていたので急いで行ったが、サイズはだいぶ落ちていた。ただムネからカタくらいはあり、すぐに終わっちゃう波ではあるがちょっとショルダーがあるので少しは何か出来て、本数も多いので、意外と練習にはいい波だな、という感じだった。</p><p>今日はカットバックを練習しよう、と思ってハウツー動画なども見てから行って、ひたすらカットバックを練習していた。 どうも緩慢なセクションまで行ってしまうともう波が無くなってカットバックが出来ないような波だったので、 ちょっともったいない気もしたが最初のカーブのセクションでカットバックをやていた。</p><p>下に行った頃には波が無くなっている事も多く、そういう時にはそこからバックサイドのボトムターンは出来ずに不発に終わる。 また、スープの下の波が無くなってしまっている事も多く、そういう場合は戻しても走り出せない。</p><p>ただ、たまに戻った所でまだパワーがあって加速出来るような事もあった。そういう時にスープに引っかかってしまうのも多いが、それは練習で解決したい。 カットバックをいつもよりも深く戻ると、そこが思ったよりも掘れててパワーのある場合がある事に気づけたのは今日の収穫だ。 これまで無駄にしていたがあそこでもう一回何か出来る感じはするな。</p><p>一方で戻っても全然駄目な波も多く、駄目な波は駄目だな、という事を再確認した。</p><p>うちのホームのショルダー無い系の波の場合、カットバックはかなりいい場所でやらないと駄目で、前の緩慢なセクションまで行っちゃうともう駄目な事が多い気がする。 こんないい所でカットバックするの？という感じの場所で意外とちょうど良かったり。 カーブしてプルアウトするのとどっちがいいのかは微妙な所だけど、練習としてはそういうセクションでやるのが良いという結論になる。</p><p>最後のバックサイドボトムターンはそもそもボトムがもう無くなってていい感じにはなかなか出来ないが、それでも目線を上げて上まで上げる動きをすると戻りが違う事は何度かあったので、この調子で改善していきたい。</p><p>あと今日はテイクオフの後に体を起こさないのを結構意識してやっていた。何回か起こしすぎてしまって降りていくだけになってしまったりもしたが、 割と上手く出来たものも結構あった。上手く行っている奴のテイクオフは結構いい感じなんじゃないか？</p><h2 id="_2026-10-09-金" tabindex="-1"><a class="header-anchor" href="#_2026-10-09-金"><span>2026-10-09 (金)</span></a></h2><p>荷物が届くのを待っていたら夕方になってしまったが、材木座がちょっと乗れそうなのでビッグバロンで入ってくる。</p><p>ヒザくらいのショアブレイクで横に行くだけって感じだが、たくさん波に乗れるので練習にはいいな、これ。 反復練習が出来るので。もうちょい波があるともっといいが。</p><p>取り回しはロングよりずっと楽な割にテイクオフはちゃんとめちゃ早い、いい感じのバランスだ。 あんまりロング要素は無く、単にめちゃテイクオフなどが早いショートって感じがする。これがミッドレングスか。いいね、気に入った。</p><h2 id="_2026-10-10-土" tabindex="-1"><a class="header-anchor" href="#_2026-10-10-土"><span>2026-10-10 (土)</span></a></h2><p>ホームポイントが小さめの波だったが少し割れてたのでBigBaronで入ってみた。 かなり良い。 ショートだとギリギリ立てる程度の波でもちゃんとフェースを走ってカットバックやちょっとしたリップの練習になる。 BigBaronはショートっぽく乗る動画が多かったので小さい波にどこまでイケるか不安があったが、 今日の波で行けるなら文句無し、という感じだ。</p><p>また、スクーターに乗せて持っていくのもサイズ的に問題無い。この取り回しの良さもちょうどいいな、ミッドレングス。気に入った。</p><h2 id="_2026-10-11-日" tabindex="-1"><a class="header-anchor" href="#_2026-10-11-日"><span>2026-10-11 (日)</span></a></h2><p>入った時はモモくらいのいまいちな波だったが、11時くらいからサイズがあがってきてハラムネくらいで割と乗れる感じに。 ショートに乗るのは久しぶりでちょっとパドルが疲れたが、割と乗れたかな。</p><p>引き続きカットバックを練習していたが今日はカットバック向きの波では無かった。</p><p>テイクオフはミッドレングスの効果か少し視野が広くなっていて、立ち上がり過ぎずに乗るのが割と出来てきている気もする。</p><h2 id="_2026-10-12-月" tabindex="-1"><a class="header-anchor" href="#_2026-10-12-月"><span>2026-10-12 (月)</span></a></h2><p>空くのを待って昼ころに入ったら、入った時は結構サイズもあってほれほれだったが、4本くらい乗ったら落ちてしまった。オフも強いしいまいち。 まぁ今日は予想が難しかったのでハズレって事で仕方ないな。</p><h2 id="_2026-10-13-火" tabindex="-1"><a class="header-anchor" href="#_2026-10-13-火"><span>2026-10-13 (火)</span></a></h2><p>今日は絶好のミッドレングス日和で、ショートだとボトムターンしておしまいって感じに見えたがミッドレングスだと厚めだけどサイズがあって最高だった。 昼過ぎてサーファーが居なくなってから少しサイズを持ち直して乗りまくってとても良かった。</p><p>カットバックの練習を最近している。ミッドレングスだと最後下から上げるのが出来ない気もするが、どうなんだろう？ ただこれまでよりもだいぶ早い位置で戻らないと自分のホームの波では駄目な事に気づいた。 こういうのをいろいろ試行錯誤出来るのはミッドレングスの良い所だな。たくさん乗れるのでいろいろ試せる。</p><p>スピードがついた後の爽快感もあるし、少し掘れた所でもコントロール出来るし、ミッドレングスは楽しいなぁ。すげー気に入った。</p><h2 id="_2026-10-14-水" tabindex="-1"><a class="header-anchor" href="#_2026-10-14-水"><span>2026-10-14 (水)</span></a></h2><p>オンショアの小波だったがビッグバロンを試してきた。 ゲットは疲れるが、ライディングは思ったより良い。</p><p>今日はコンディションがかなり悪く、割れてもすぐ無くなるような波ばかりだったが、 ビッグバロンだとなくなったりスープになった所も乗り越えていけるので、 ショートでは無理なコンディションでも意外と楽しめた。 めっちゃ疲れるが、それでも乗れないショートよりはミッドの方がいいかな。</p><p>昨日は結構オフだったので、オフでもオンでも結構いける事が分かった。 風には強いな。 ただ風が強いとバイクで運ぶ時にちょっと怖いな。</p><p>オンショアはミッド向きではない、というyoutubeなども結構見かけたが、自分的にはミッド結構いい気がした。</p><h2 id="_2026-10-19-月" tabindex="-1"><a class="header-anchor" href="#_2026-10-19-月"><span>2026-10-19 (月)</span></a></h2><p>久しぶりにオンショアが強く吹いてちょっと波が出たので材木座で<a href="./BigBaron.html">BigBaron</a>で入る。 オンショアは向いてないと言われがちだしそういう要素も理解は出来るが、ミッドの良さも結構あるよな。 波がすぐ無くなっちゃう時に少しつなげられる事がある、みたいな。 少し長い波が無いと駄目だが、少し長く乗れる波があればミッドの良さは生きる。</p><p>今日はあまり良い波は無かったが、3〜4本くらいは少し練習になる波があった、という感じ。 カットバックの熟練度を上げつつ、少し掘れ気味のフェースを走るのに慣れる練習。</p><h2 id="_2026-10-20-火" tabindex="-1"><a class="header-anchor" href="#_2026-10-20-火"><span>2026-10-20 (火)</span></a></h2><p>昨日と同じ感じだったので材木座に入る。昨日よりは少しサイズがあり、風が落ち着いてきたあとも少し波が残ったので昨日よりは良かった。 カットバックとローラーコースターを何本かメイク。 技以外でもある程度掘れた所をライディングしてボードコントロールの練習という感じ。</p><h2 id="_2026-10-25-日" tabindex="-1"><a class="header-anchor" href="#_2026-10-25-日"><span>2026-10-25 (日)</span></a></h2><p>ここ数日はサーフィンばかりだったが、毎日疲れててこのログの更新も出来ていなかった。 波はそんなに凄く良い日は無かったが、毎日それなりに出来る感じで、まぁこんだけ出来ればいいか、という気はしている。</p><p>波の無い日に<a href="./BigBaron.html">BigBaron</a>で練習していた成果が出て、テイクオフが上達した気がする。 本当はここでこういう感じで乗りたい、というイメージが出来たおかげで、そこに向けてパドルを頑張ったり乗った後もスムーズに動ける事は増えた気がする。</p><p>あとここ数日はラウンドハウスカットバックがちゃんとスープ側に入る波が多くて、カットバックの練習をしていた。 カットバックはだいぶ上達した気がする。</p><h2 id="_2026-10-26-月" tabindex="-1"><a class="header-anchor" href="#_2026-10-26-月"><span>2026-10-26 (月)</span></a></h2><p>今日は今回の台風で一番のベストウェーブという感じか。掘れ上がる前にパドルで乗らないとやばい感じになる事もあったが、基本的には乗りやすい波だった。</p><p>今日はカービングっぽいカットバックを何本かやっていて、最後の上に上げるのは結構出来たかな、と思っている。 カットバックは波によっていろいろだが、だいぶいろいろなパターンが出来るようになってきたかな。</p><h2 id="_2026-10-30-金" tabindex="-1"><a class="header-anchor" href="#_2026-10-30-金"><span>2026-10-30 (金)</span></a></h2><p>オンショアが強くなって来たがサイズもあがってきてミッドレングスで入ってみた。 まぁまぁ掘れててショートの方が楽そうではあるが途中緩慢な所もつないで長く乗れるので<a href="./BigBaron.html">BigBaron</a>にはBigBaronの良さがあるな。</p><p>取り回しの悪さからテイクオフはミスってる事が多いが、テイクオフをミスってもそのまま乗れてしまうので、テイクオフの練習としては微妙だがライディングは楽しめる。 スピードの付け方や体の使い方は乗れる時間が長いのでミッドレングスの方がいいよな。</p><p>一度乗るとかなりインサイドまで行ってしまう上に戻る時はオンショアでぱしゃぱしゃ波に当たりながらなのでめちゃパドルが疲れた。 ただたくさん乗れたので楽しかった。ミッドレングスはいいね。</p><h2 id="_2026-11-01-日" tabindex="-1"><a class="header-anchor" href="#_2026-11-01-日"><span>2026-11-01 (日)</span></a></h2><p>昨日もビッグバロンで入る。クリーンで結構サイズもあるミッドレングス日和。だんだんと体の使い方や波の使い方が上手くなっている気はする。</p><p>今日は<a href="./HT2.html">HT2</a>で入る。サイズはムネカタくらいか？ショルダーが無いのも多いがカーブやカットバックが一回ちゃんと入るくらいはあるのもあり、 全体としては悪くない。 カットバックの最後のスープに当てる所はまぁまぁ出来るようになってきたが、 ホームポイントはあまり横に走れる感じでは無いのでカービングっぽいカットバックになる。まぁこれはいいと思っている。</p><h2 id="_2026-11-02-月" tabindex="-1"><a class="header-anchor" href="#_2026-11-02-月"><span>2026-11-02 (月)</span></a></h2><p>今日はミッドレングスで入る。オンショアでそれなりにまとまりも無いがたまにちょっとしたセットは入ってくるし、たまに風が弱くなってまとまってきたりもする。 入っていればそれなりのもある、という感じ。</p><p>ミッドレングスだと途中波が無くなってしまう所も走っていけるので、こういう日は意外と良い。 テイクオフからパワーゾーンをキープする練習をしていた。 具体的にこれ、というよりも、たくさん乗って体の使い方を改善してきたい。</p><p>あとテイクオフで立ち上がるのをやめたいなぁ、という気もしている。 最近波が早い時などには乗った瞬間に既にライディング姿勢に入っていていい感じなのだが、 普段もこれでいいんだよなぁ、と思っていて、いつもそれにしたいと思っている。 これは波に乗る時は他の事をいろいろと考えていて忘れがちなので、意識したいなぁ、という思いをここに書いておく。</p><h2 id="_2026-11-07-土" tabindex="-1"><a class="header-anchor" href="#_2026-11-07-土"><span>2026-11-07 (土)</span></a></h2><p>ここ数日はサーフィンばかりしていた。</p><ul><li>11月4日 ミッドだといい波</li><li>11月5日 2ラウンド入る。午前中はショートでまずまず、夕方はミッドでまずまず。</li><li>11月6日 ミッドでいい波</li></ul><p>凄くいい波という感じにはならなかったが、ショートでもまぁまぁな日もあったしミッドではいつも凄く良い波。 ミッドにもだいぶ慣れてきた。</p><p>カットバックはだいぶ上達してきたとは思う。正直上手く行かない時に波がいけないのか自分のライディングの問題かは良く分からない所もあるが、 この辺はグラデーションなので上手く出来る時を積み重ねて慣れていけばいいかな、とは思う。</p><p>ステップバックも割と慣れてきているように思う。ただ出来ずにボトムターンに入ってしまう事もある。この辺は練習か。 ミッドだと明らかにリップやローラーコースターの時にはステップバックしてないといい感じにならないので、練習には良い。</p><p>ミッドに慣れてきた結果、少し掘れた所でいろいろやりたくなってきてはいる。<a href="./BigBaron.html">BigBaron</a>は意外とアップスとかも出来る感じなので、 小さい波の掘れた所で遊ぶのも結構遊べる。ただどういう感じの事をやっていくのがいいのか自分の中で固まっていないので、 もう少しいろいろやっていって可能性を模索したい。</p><p>昨日はミッドのテイクオフで立ち上がらずにそのままライディングする練習をしていた。 ミッドだと立ち上がらずにそのままライディングするのも難しくなく、波が早い時などは自然とそうなるのだけれど、 普段からそれをクセつけようと練習している。 こういうのはミッドで練習する方がいいかもしれん。波の本数も多いし。</p><p>しばらくミッド乗った後にショート乗ると、テイクオフが上手くなっていると思う。一方ライディングはあまり改善が見られない気がする。 この辺は波にもよるので曖昧だが。</p><p>ミッドで体の使い方を改善したいなぁ、と思っているのだが、単に乗っているだけでそれが出来ているのかが良く分からない。 パワーゾーンに乗っている時間は長いのでそこを上手く使う事に関しては多少の上達はあると思うが。</p><p>ミッドに慣れてきた結果、単に乗るだけでは無く課題を持って練習したいなぁ、という気もして来ているが、 ショートの練習としてのミッドの課題、というのが普通はどういうものか、良く分からないな。 この辺は誰かに教えてもらいたい気もする。</p>`,138)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};